from collections import Counter
import itertools


def task_func(d):
    """
    Count how often each integer appears across all list values of the dictionary.

    Parameters:
        d (dict): A dictionary whose values are lists of integers.

    Returns:
        dict: A dictionary where each key is an integer found in the lists, and the
              value is how many times it shows up across all the lists.
    """
    count_dict = Counter(itertools.chain.from_iterable(d.values()))
    return dict(count_dict)


if __name__ == "__main__":
    example = {'a': [1, 2, 3, 1], 'b': [3, 4, 5], 'c': [1, 2]}
    print(task_func(example))  # {1: 3, 2: 2, 3: 2, 4: 1, 5: 1}
    print(task_func({}))       # {}
```

`itertools.chain.from_iterable` joins all the lists into one stream without making a new list. `Counter` then counts every integer, and the result is returned as a plain `dict`.
